/* Optional daily shortlist; each account owns its preference and task selection. */
(()=>{'use strict';if(!document.body.classList.contains('shared-app'))return;
const q=s=>document.querySelector(s),day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const prefs=()=>window.SamandisPreferences;
function plan(){const p=prefs()?.get('today-plan',null);return p?.day===day()&&Array.isArray(p.ids)?p.ids:[]}
function eligible(){return tasks.filter(t=>own(t)||collaborating(t))}
async function save(key,value){try{await prefs().set(key,value);sync();return true}catch(e){message('ذخیره نشد؛ دوباره تلاش کنید.');return false}}
function choose(){selectedTask=null;const ids=new Set(plan()),list=eligible();modal(modalHead('انتخاب کارهای امروز')+'<p class="shared-meta">کارهایی را که امروز می‌خواهید انجام دهید انتخاب کنید. مهلت و مسئول کار تغییر نمی‌کند.</p><form id="todayPlanForm"><div class="today-plan-options">'+list.map(t=>'<label class="checkbox-choice"><input type="checkbox" name="task" value="'+esc(t.id)+'" '+(ids.has(t.id)?'checked':'')+'><span>'+esc(t.title)+(t.status==='done'?' · تمام‌شده':'')+'</span></label>').join('')+'</div><button class="primary" type="submit">ذخیره برنامه امروز</button></form>');q('#todayPlanForm').onsubmit=async e=>{e.preventDefault();const ids=new FormData(e.target).getAll('task');if(ids.length>80)return message('حداکثر ۸۰ کار برای امروز انتخاب کنید.');const b=e.target.querySelector('button');b.disabled=true;if(await save('today-plan',{day:day(),ids}))q('#sharedDialog').close();else b.disabled=false}}
let expanded=true;
function sync(){const me=typeof mine==='function'&&mine(),enabled=!!prefs()?.get('today-plan-enabled',false);const menu=q('#accountMorePanel');let toggle=q('#todayPlanToggle');if(menu&&!toggle){toggle=document.createElement('button');toggle.type='button';toggle.id='todayPlanToggle';toggle.className='account-settings-link';toggle.onclick=async()=>{await save('today-plan-enabled',!prefs().get('today-plan-enabled',false))};menu.append(toggle)}if(toggle){toggle.hidden=!me;toggle.textContent=enabled?'حذف «کارهای امروز» از سایدبار':'افزودن «کارهای امروز» به سایدبار';toggle.setAttribute('aria-pressed',String(enabled))}
let box=q('#todayPlan');if(!me||!enabled||window.SAMANDIS_PERSONAL_MODE){box?.remove();return}if(!box){box=document.createElement('details');box.id='todayPlan';box.open=expanded;box.addEventListener('toggle',()=>expanded=box.open);q('#deskNav')?.after(box)}const ids=new Set(plan()),list=eligible().filter(t=>ids.has(t.id));box.innerHTML='<summary>کارهای امروز <small>'+fa(list.length)+'</small></summary><div class="today-plan-list">'+list.map(t=>'<button type="button" data-today-task="'+esc(t.id)+'"><span class="today-plan-dot '+(t.status==='done'?'done':'')+'">'+(t.status==='done'?'✓':'')+'</span><span>'+esc(t.title)+'</span></button>').join('')+'</div><button type="button" class="today-plan-add">＋ انتخاب کارهای امروز</button>';box.querySelector('.today-plan-add').onclick=choose;box.querySelectorAll('[data-today-task]').forEach(b=>b.onclick=()=>detail(b.dataset.todayTask))}
const old=render;render=function(...args){const r=old(...args);sync();return r};document.addEventListener('samandis-preferences-loaded',sync);setInterval(sync,60000);sync();
})();
